<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use ReadyFinance\{Core,Finance,LedgerService,Accounting,TransactionEditingService,AccountManagementService,Fault};
$c=new Core();if(!str_starts_with((string)$c->query('SELECT DATABASE()')->fetchColumn(),'readyfinance_entrytest_'))throw new RuntimeException('Isolated test installation required.');
$h=(int)$c->query('SELECT MIN(id) FROM households')->fetchColumn();$u=(int)$c->query('SELECT MIN(id) FROM users')->fetchColumn();$f=new Finance($c);$engine=new Accounting($c);$ledger=new LedgerService($c);$key='ledger-test:'.bin2hex(random_bytes(4));$count=0;
function ok($yes,$label){global $count;if(!$yes)throw new RuntimeException('FAIL: '.$label);$count++;echo 'PASS: '.$label.PHP_EOL;}
function rejects($fn,$label){try{$fn();}catch(Fault $e){ok(true,$label);return;}throw new RuntimeException('FAIL: '.$label);}
function eq($a,$b){return bccomp((string)$a,(string)$b,6)===0;}
$money=$f->create($h,$u,'account',['name'=>'Ledger pagination bank '.$key,'type'=>'bank','opening'=>'100','date'=>'2024-12-31'],$key.':bank');$acct=$c->scope('accounts',$money['uuid'],$h);$leaf=$c->one('SELECT * FROM ledger_accounts WHERE household_id=? AND id=?',[$h,$acct['ledger_id']]);$expense=$c->one("SELECT uuid FROM categories WHERE household_id=? AND name='Groceries'",[$h]);$income=$c->one("SELECT uuid FROM categories WHERE household_id=? AND name='Salary'",[$h]);
$c->atomic(function()use($engine,$h,$u,$money,$income,$key){for($i=1;$i<=1005;$i++)$engine->postInTransaction($h,$u,['type'=>'income','amount'=>'1.01','date'=>'2025-01-01','description'=>'Pagination credit '.str_pad((string)$i,4,'0',STR_PAD_LEFT),'account_uuid'=>$money['uuid'],'category_uuid'=>$income['uuid']],$key.':'.$i);});
$expenseEntry=$engine->post($h,$u,['type'=>'expense','amount'=>'10','date'=>'2025-01-02','description'=>'Find this merchant','account_uuid'=>$money['uuid'],'category_uuid'=>$expense['uuid']],$key.':expense');
$all=$ledger->view($h,['kind'=>'money','uuid'=>$money['uuid'],'order'=>'oldest']);ok($all['from']==='2024-12-31'&&$all['entries']===1007,'Default ledger starts with earliest opening, beyond 1000 entries');ok(count($all['rows'])===50&&$all['pages']===21,'Ledger is server-paged without silently truncating history');ok(eq($all['rows'][0]['running_balance'],'100')&&eq($all['rows'][49]['running_balance'],'149.49'),'First page balances include same-day journal sequence');
$middle=$ledger->view($h,['uuid'=>$leaf['uuid'],'page'=>'2','order'=>'oldest']);ok(eq($middle['rows'][0]['running_balance'],'150.50'),'Running balance continues across pages');ok(!array_intersect(array_column($all['rows'],'uuid'),array_column($middle['rows'],'uuid')),'Adjacent pages do not repeat entries');
$last=$ledger->view($h,['uuid'=>$leaf['uuid'],'page'=>'21','order'=>'oldest']);ok(count($last['rows'])===7&&end($last['rows'])['uuid']===$expenseEntry['uuid'],'Final page includes entries after the former 1000-row cap');ok(eq($last['closing'],'1105.05')&&eq(end($last['rows'])['running_balance'],$last['closing']),'Last running balance matches full ledger closing');
$reverse=$ledger->view($h,['uuid'=>$leaf['uuid']]);ok($reverse['rows'][0]['uuid']===$expenseEntry['uuid']&&eq($reverse['rows'][0]['running_balance'],'1105.05'),'Newest-first order retains chronological balances');
$range=$ledger->view($h,['uuid'=>$leaf['uuid'],'from'=>'2025-01-02','to'=>'2025-01-02']);ok(eq($range['opening'],'1115.05')&&eq($range['debit'],'0')&&eq($range['credit'],'10')&&eq($range['closing'],'1105.05'),'Date-filtered opening and totals reconcile');
$found=$ledger->view($h,['uuid'=>$leaf['uuid'],'search'=>'Find this merchant']);ok($found['matched']===1&&eq($found['rows'][0]['running_balance'],$last['closing'])&&eq($found['closing'],$last['closing']),'Search preserves balances from entries outside search results');ok($ledger->view($h,['uuid'=>$leaf['uuid'],'search'=>'%'])['matched']===0,'Search treats percent as literal text');ok($ledger->view($h,['uuid'=>$leaf['uuid'],'page'=>'99999'])['page']===21,'Out-of-range pages clamp to final page');
$editor=new TransactionEditingService($c);$details=$editor->details($h,$expenseEntry['uuid']);ok(count($details['line_items'])===2&&$details['line_items'][0]['name']==='Groceries','Transaction details contain named debit and credit lines');$payload=$details['payload'];$payload['amount']='12';$updated=$editor->edit($h,$u,['uuid'=>$expenseEntry['uuid'],'row_version'=>$expenseEntry['row_version'],'reason'=>'Correct merchant amount','payload'=>$payload],$key.':edit');
$corrected=$ledger->view($h,['uuid'=>$leaf['uuid'],'search'=>'Find this merchant']);ok($corrected['matched']===2&&$corrected['entries']===1009&&eq($corrected['closing'],'1103.05'),'Ledger retains original, reversal and replacement after editing');ok($editor->details($h,$expenseEntry['uuid'])['replacement_uuid']===$updated['uuid'],'Superseded entry links to corrected transaction');
rejects(fn()=>$ledger->view($h,['uuid'=>Core::uuid()]),'Unavailable ledger is scoped');$foreign=$c->query('SELECT id FROM households WHERE id<>? LIMIT 1',[$h])->fetchColumn();if(!$foreign)$foreign=$c->insert('households',['uuid'=>Core::uuid(),'name'=>'Foreign ledger test','currency'=>'PKR','timezone'=>'Asia/Karachi','created_at'=>Core::now()]);$foreignId=$c->ledger((int)$foreign,'Private ledger','asset');$foreignUuid=$c->one('SELECT uuid FROM ledger_accounts WHERE id=?',[$foreignId])['uuid'];rejects(fn()=>$ledger->view($h,['uuid'=>$foreignUuid]),'Foreign household ledger cannot be read');
$group=$c->one("SELECT uuid FROM ledger_accounts WHERE household_id=? AND system_key='chart_root_asset'",[$h]);rejects(fn()=>$ledger->view($h,['uuid'=>$group['uuid']]),'Parent groups cannot masquerade as posting ledgers');rejects(fn()=>$ledger->view($h,['uuid'=>$leaf['uuid'],'from'=>'2025-02-01','to'=>'2025-01-01']),'Reversed date range rejected');rejects(fn()=>$ledger->view($h,['uuid'=>$leaf['uuid'],'page'=>'0']),'Invalid page rejected');
$empty=$f->create($h,$u,'account',['name'=>'Empty ledger '.$key,'type'=>'cash','opening'=>'0'],$key.':empty');$manage=new AccountManagementService($c);$emptyRow=$c->scope('accounts',$empty['uuid'],$h);$manage->update($h,$u,['uuid'=>$empty['uuid'],'expected_name'=>$emptyRow['name'],'expected_active'=>$emptyRow['active'],'action'=>'archive'],$key.':archive',true);$emptyView=$ledger->view($h,['kind'=>'money','uuid'=>$empty['uuid']]);ok(!$emptyView['account']['active']&&$emptyView['entries']===0&&$emptyView['pages']===1,'Archived empty accounts retain readable ledgers');
ok(!$c->one('SELECT journal_id FROM journal_lines WHERE household_id=? GROUP BY journal_id HAVING SUM(debit)<>SUM(credit)',[$h]),'Ledger fixture and correction journals all balance');
echo $count.' ledger checks passed.'.PHP_EOL;
